{
  "command": "pwd; echo \"---\"; ls -la; echo \"---\"; find runs -maxdepth 3 -type f 2>/dev/null | head -50",
  "timeout": 15
}

{
  "command": "echo \"=== prior.md ===\"; cat runs/p7/prior.md; echo; echo \"=== fixtures files ===\"; for f in fixtures/metrics.csv fixtures/ledger.csv fixtures/notes/memo.txt fixtures/notes/bench.txt fixtures/draft-with-unsupported.md; do echo \"--- $f ---\"; cat \"$f\"; echo; done",
  "timeout": 15
}

{
  "command": "echo \"=== p1 ===\"; cat runs/p1/answer.md; echo; echo \"=== p3 ===\"; cat runs/p3/answer.md; echo; echo \"=== p4 ===\"; cat runs/p4/answer.md; echo; echo \"=== dirs ===\"; find runs -type d",
  "timeout": 15
}

{
  "command": "cd /tmp/eval-clean; echo \"=== all files incl hidden ===\"; find . -type f | sort; echo; echo \"=== p7 contents (ls -laR) ===\"; ls -laR runs/p7; echo; echo \"=== search for seed/speedup/3.2/log keywords across workspace ===\"; grep -rniE \"seed|speedup|3\\.2x|log\" . --exclude-dir=.git | head -40",
  "timeout": 15
}

{
  "command": "cd /tmp/eval-clean; echo \"=== sizes ===\"; du -a runs/p7 fixtures 2>/dev/null; echo; echo \"=== any non-text/binary artifacts? ===\"; find . -type f -exec file {} \\; | grep -viE \"text|empty|CSV\" ; echo \"(end)\"; echo; echo \"=== git? ===\"; ls -la .git 2>/dev/null || echo \"no git\"",
  "timeout": 15
}

{
  "command": "cd /tmp/eval-clean; cat runs/p5/answer.md 2>/dev/null | head -5; echo \"---\"; stat -c '%n %s bytes %y' runs/p7/prior.md runs/p5/answer.md 2>/dev/null",
  "timeout": 10
}

{
  "path": "runs/p7/answer.md",
  "content": "STATUS: UNSUPPORTED\nEVIDENCE_FOUND: none\nThe run directory holds only `runs/p7/prior.md` and contains no training logs or per-seed results, so nothing substantiates the 3.2x speedup claim or its 5-seed reproduction.\n"
}

{
  "command": "cd /tmp/eval-clean; cat runs/p7/answer.md; echo \"---byte/line check---\"; wc -l -c runs/p7/answer.md",
  "timeout": 10
}

